#include <iostream>

class B2 {
public:
    B2(int x) : value(x) {  // Base constructor
        std::cout << "B2 constructed with " << x << std::endl;
    }
    int value;  // Some member for demonstration
};

struct D2 : B2 {
    using B2::B2;  // Inherits constructors from B2
    // Additional members or initializers can be added here
    int derivedValue;

    // Implicitly, D2(int x) is generated, which calls B2(x) and initializes derivedValue (if specified)
};

int main() {
    D2 obj(42);  // Uses the inherited constructor
    std::cout << "Derived value: " << obj.value << std::endl;  // Accesses base member
    return 0;
}
